<style>
.aiads{--a:#5b35c5;--ink:#192233;--muted:#748094;max-width:1180px;margin:20px auto;padding:0 20px 32px;color:var(--ink)}.aiads-head{display:flex;align-items:flex-start;justify-content:space-between;margin:10px 0 22px}.aiads-kicker{color:var(--a);font-weight:700;font-size:12px;text-transform:uppercase;letter-spacing:.08em}.aiads h1{font-size:28px;margin:6px 0}.aiads-head p,.card-title p,.muted{color:var(--muted);margin:0;font-size:13px}.aiads-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.aiads-card{background:#fff;border:1px solid #e6e9ef;border-radius:14px;padding:20px;margin-bottom:16px;box-shadow:0 4px 16px #18243a08}.card-title{display:flex;align-items:flex-start;gap:12px;margin-bottom:18px}.card-title h2{font-size:17px;margin:0 0 4px}.aiads-icon{background:#f0ebff;color:var(--a);font-weight:800;border-radius:10px;padding:8px 12px}.aiads-pill{border-radius:999px;padding:6px 10px;font-size:12px;background:#fff4db;color:#8c5b00;white-space:nowrap}.aiads-pill.ok{background:#e7f7ef;color:#177245}.aiads-note{padding:12px 14px;background:#f7f5ff;color:#514579;border:1px solid #e9e3ff;border-radius:10px;font-size:13px;line-height:1.5;margin:12px 0}.aiads-alert{padding:11px 13px;border-radius:9px;margin:0 0 14px}.aiads-alert.success{background:#eaf8f0;color:#156a3a}.aiads-alert.error{background:#fff0ef;color:#9b2e26}.aiads-button{display:inline-flex;padding:10px 15px;border:0;border-radius:9px;font-weight:700;text-decoration:none;cursor:pointer}.aiads-button.primary{background:var(--a);color:#fff}.aiads-button.secondary{background:#ece8fb;color:#4c2aa9}.connected{display:flex;gap:10px;align-items:center;margin-bottom:12px}.connected strong{color:#18774b}.aiads-assets{display:grid;grid-template-columns:1fr 1fr;gap:12px}.aiads label{display:block;font-size:12px;font-weight:700;color:#465166}.aiads input,.aiads select,.aiads textarea{box-sizing:border-box;display:block;width:100%;margin-top:6px;border:1px solid #dce1e9;border-radius:8px;padding:10px;background:#fff;color:#1d2635;font:inherit}.aiads textarea{resize:vertical}.aiads-assets button{align-self:end}.inline-form{display:inline-block;margin-top:12px}.link-button{background:none;border:0;color:#775dcd;text-decoration:underline;cursor:pointer}.plan-row{display:flex;justify-content:space-between;padding:12px 0;border-bottom:1px solid #eef0f3}.composer{margin-top:0}.aiads-form{display:grid;grid-template-columns:1fr 1fr;gap:14px}.aiads-form .wide{grid-column:1/-1}.campaign-row{display:flex;align-items:center;gap:18px;padding:13px 0;border-top:1px solid #eef0f3}.campaign-row div{flex:1}.campaign-row p{font-size:12px;color:var(--muted);margin:4px 0 0}.aiads-empty{padding:24px;text-align:center;background:#fafbfc;border-radius:10px;color:var(--muted)}@media(max-width:767px){.aiads-grid{grid-template-columns:1fr}.aiads-assets{grid-template-columns:1fr}.aiads-head{display:block}.aiads-head .aiads-pill{display:inline-block;margin-top:10px}.campaign-row{align-items:flex-start;flex-wrap:wrap}.aiads{padding:0 12px 24px}}
</style>
